'use client';

import { useState, useEffect } from 'react';
import dynamic from 'next/dynamic';
import Header from '@/components/Header';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import { useDictionary } from '@/hooks/useDictionary';

export interface ExtendedDictionaryItem {
  id: string;
  word: string;
  definitions?: { meaning: string }[];
  full_definition_in_html?: string;
  tanim?: { meaning: string };
  dictionaryName?: string;
}

const SozlukEkrani = dynamic(() => import('@/components/SozlukEkrani'), {
  loading: () => <LoadingSkeleton />,
  ssr: false,
});

export default function Page() {
  const [metinBoyutu, setMetinBoyutu] = useState<number>(16);
  const [karanlikMod, setKaranlikMod] = useState<boolean>(false);
  const [tema, setTema] = useState<'light' | 'dark'>('light');

  // Gerçek sözlük verilerini yükleyen hook
  const dictionary = useDictionary();

  // Karanlık mod değişimini Tailwind için HTML root'una uygula
  useEffect(() => {
    if (karanlikMod) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [karanlikMod]);

  const handleTemaChange = (yeniTema: 'light' | 'dark') => {
    setTema(yeniTema);
    setKaranlikMod(yeniTema === 'dark');
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 transition-colors">
      <Header
        tema={tema}
        metinBoyutu={metinBoyutu}
        karanlikMod={karanlikMod}
        setMetinBoyutu={setMetinBoyutu}
        setKaranlikMod={setKaranlikMod}
        setTema={handleTemaChange}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <SozlukEkrani
          words={(dictionary.words || []) as ExtendedDictionaryItem[]}
          loading={dictionary.loading}
          totalCount={dictionary.words?.length || 428000}
        />
      </main>
    </div>
  );
}